  /// Chosen change address for the current balance (null: automatic).
  String? get _pivxChange =>
      _fromShield ? _pivxShieldChangeAddress : _pivxChangeAddress;

  Amount? _cachedAmountToSend;
  String? _address;

  bool _addressToggleFlag = false;

  bool _cryptoAmountChangeLock = false;
  late VoidCallback onCryptoAmountChanged;

  Future<void> scanWebcam() async {
    try {
      final qrResult = await showDialog<String>(
        context: context,
        builder: (context) => const QrCodeScannerDialog(),
      );
      if (qrResult == null) {
        Logging.instance.w("Qr scanning cancelled");
      } else {
        try {
          _processQrCodeData(qrResult);
        } catch (e, s) {
          Logging.instance.e(
            "Error processing QR code data",
            error: e,
            stackTrace: s,
          );
        }
      }
    } catch (e, s) {
      Logging.instance.e(
        "Error opening QR code scanner dialog",
        error: e,
        stackTrace: s,
      );
    }
  }

  /// A Preview click while one is running is ignored: two would build two
  /// transactions.
  bool _previewing = false;

  Future<void> previewSend() async {
    if (_previewing) return;
    _previewing = true;
    try {
      await _preview();
    } finally {
      _previewing = false;
    }
  }

  Future<void> _preview() async {
    final wallet = ref.read(pWallets).getWallet(walletId);

    final Amount amount = ref.read(pSendAmount)!;
    final Amount availableBalance = _spendable;

    final coinControlEnabled = ref
        .read(prefsChangeNotifierProvider)
        .enableCoinControl;

    if (!coinControlEnabled || ref.read(desktopUseUTXOs).isEmpty) {
      // confirm send all
      if (amount == availableBalance) {
        final bool? shouldSendAll = await showDialog<bool>(
          context: context,
          useSafeArea: false,
          barrierDismissible: true,
          builder: (context) {
            return DesktopDialog(
              maxWidth: 450,
              maxHeight: double.infinity,
              child: Padding(
                padding: const EdgeInsets.only(left: 32, bottom: 32),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Text(
                          l10n.sendConfirmSendAll,
                          style: STextStyles.desktopH3(context),
                        ),
                        const DesktopDialogCloseButton(),
                      ],
                    ),
                    const SizedBox(height: 12),
                    Padding(
                      padding: const EdgeInsets.only(right: 32),
                      child: Text(
                        l10n.sendConfirmSendAllText,
                        textAlign: TextAlign.left,
                        style: STextStyles.desktopTextExtraExtraSmall(context)
                            .copyWith(fontSize: 18),
                      ),
                    ),
                    const SizedBox(height: 40),
                    Padding(
                      padding: const EdgeInsets.only(right: 32),
                      child: Row(
                        children: [
                          Expanded(
                            child: SecondaryButton(
                              buttonHeight: ButtonHeight.l,
                              label: l10n.commonCancel,
                              onPressed: () {
                                Navigator.of(context).pop(false);
                              },
                            ),
                          ),
                          const SizedBox(width: 16),
                          Expanded(
                            child: PrimaryButton(
                              buttonHeight: ButtonHeight.l,
                              label: l10n.commonYes,
                              onPressed: () {
                                Navigator.of(context).pop(true);
                              },
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            );
          },
        );

        if (shouldSendAll == null || shouldSendAll == false) {
          // cancel preview
          return;
        }
      }
    }

    // A PIVX.name name: look it up and check it first. The transaction
    // pays the address that was proven, never the name's text.
    var recipient = _address!;
    PivxNameVerified? pivxName;
    final name = pivxNameFor(coin, _address);
    if (name != null) {
      if (!mounted) return;
      pivxName = await lookUpPivxNameForSend(
        context: context,
        coin: coin,
        name: name,
        contacts: ref.read(addressBookServiceProvider).contacts,
      );
      if (pivxName == null || !mounted) return;
      recipient = pivxName.address;
    }

    bool wasCancelled = false;
    try {
      if (mounted) {
        unawaited(
          showDialog<dynamic>(
            context: context,
            useSafeArea: false,
            barrierDismissible: false,
            builder: (context) {
              return DesktopDialog(
                maxWidth: 400,
                maxHeight: double.infinity,
                child: Padding(
                  padding: const EdgeInsets.all(32),
                  child: BuildingTransactionDialog(
                    coin: wallet.info.coin,
                    onCancel: () {
                      wasCancelled = true;

                      Navigator.of(context).pop();
                    },
                  ),
                ),
              );
            },
          ),
        );
      }

      final time = Future<dynamic>.delayed(const Duration(milliseconds: 2500));

      TxData txData;

      // PIVX send settings: the balance spent, fee subtraction and the
      // change address.
      final fromShield = _fromShield;
      final pivxOtherData = <String, dynamic>{
        if (fromShield) kPivxFromShield: true,
        if (coin is Pivx && _pivxSubtractFee) kPivxSubtractFee: true,
        if (!fromShield && _pivxChangeAddress != null)
          kPivxChangeAddress: _pivxChangeAddress,
        if (fromShield && _pivxShieldChangeAddress != null)
          kPivxChangeAddress: _pivxShieldChangeAddress,
      };

      final Future<TxData> txDataFuture = wallet.prepareSend(
        txData: TxData(
          recipients: [
            TxRecipient(
              address: recipient,
              amount: amount,
              isChange: false,
              addressType: wallet.cryptoCurrency.getAddressType(recipient)!,
            ),
          ],
          // PIVX: only a shield recipient gets the (encrypted) memo.
          memo: _sendsToShield && memoController.text.isNotEmpty
              ? memoController.text
              : null,
          feeRateType: FeeRateType.average,
          utxos: (coinControlEnabled && ref.read(pDesktopUseUTXOs).isNotEmpty)
              ? ref.read(pDesktopUseUTXOs)
              : null,
          otherData: pivxOtherData.isEmpty ? null : jsonEncode(pivxOtherData),
        ),
      );

      final results = await Future.wait([txDataFuture, time]);

      txData = results.first as TxData;

      if (!wasCancelled && mounted) {
        txData = txData.copyWith(note: noteController.text.trim());
        // pop building dialog
        Navigator.of(context, rootNavigator: true).pop();

        unawaited(
          showDialog(
            context: context,
            builder: (context) => DesktopDialog(
              maxHeight: MediaQuery.of(context).size.height - 64,
              maxWidth: 580,
              child: ConfirmTransactionView(
                txData: txData,
                walletId: walletId,
                pivxName: pivxName,
                onSuccess: clearSendForm,
                routeOnSuccessName: DesktopHomeView.routeName,
              ),
            ),
          ),
        );
      }
    } catch (e, s) {
      Logging.instance.e("Desktop send: ", error: e, stackTrace: s);
      // Cancelled: the dialog is closed already, and the error is moot.
      if (mounted && !wasCancelled) {
        // pop building dialog
        Navigator.of(context, rootNavigator: true).pop();

        unawaited(
          showDialog<void>(
            context: context,
            builder: (context) {
              return DesktopDialog(
                maxWidth: 450,
                maxHeight: double.infinity,
                child: Padding(
                  padding: const EdgeInsets.only(left: 32, bottom: 32),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Text(
                            l10n.sendTransactionFailed,
                            style: STextStyles.desktopH3(context),
                          ),
                          const DesktopDialogCloseButton(),
                        ],
                      ),
                      const SizedBox(height: 12),
                      Padding(
                        padding: const EdgeInsets.only(right: 32),
                        child: Text(
                          e.toString(),
                          textAlign: TextAlign.left,
                          style: STextStyles.desktopTextExtraExtraSmall(context)
                              .copyWith(fontSize: 18),
                        ),
                      ),
                      const SizedBox(height: 40),
                      Row(
                        children: [
                          Expanded(
                            child: SecondaryButton(
                              buttonHeight: ButtonHeight.l,
                              label: l10n.commonOk,
                              onPressed: () {
                                Navigator.of(
                                  context,
                                  rootNavigator: true,
                                ).pop();
                              },
                            ),
                          ),
                          const SizedBox(width: 32),
                        ],
                      ),
                    ],
                  ),
                ),
              );
            },
          ),
        );
      }
    }
  }

  void clearSendForm() {
    if (!mounted) {
      return;
    }
    sendToController.text = "";
    cryptoAmountController.text = "";
    baseAmountController.text = "";
    memoController.text = "";
    nonceController.text = "";
    noteController.text = "";
    _address = "";
    _addressToggleFlag = false;
    _setValidAddressProviders("");
    setState(() {});
  }

  void _cryptoAmountChanged() async {
    if (!_cryptoAmountChangeLock) {
      final cryptoAmount = ref
          .read(pAmountFormatter(coin))
          .tryParse(cryptoAmountController.text);
      final Amount? amount;
      if (cryptoAmount != null) {
        amount = cryptoAmount;
        if (_cachedAmountToSend != null && _cachedAmountToSend == amount) {
          return;
        }

        _cachedAmountToSend = amount;

        final price = ref
            .read(priceAnd24hChangeNotifierProvider)
            .getPrice(coin)
            ?.value;

        if (price != null && price > Decimal.zero) {
          final String fiatAmountString = (amount.decimal * price)
              .toAmount(fractionDigits: 2)
              .fiatString(
                locale: ref.read(localeServiceChangeNotifierProvider).locale,
              );

          baseAmountController.text = fiatAmountString;
        }
      } else {
        amount = null;
        _cachedAmountToSend = null;
        baseAmountController.text = "";
      }

      ref.read(pSendAmount.notifier).state = amount;
    }
  }

  void _processQrCodeData(String qrCodeData) {
    try {
      final paymentData = AddressUtils.parsePaymentUri(
        qrCodeData,
        logging: Logging.instance,
      );

      if (paymentData != null &&
          paymentData.coin?.uriScheme == coin.uriScheme) {
        _applyUri(paymentData);
      } else {
        _address = qrCodeData.split("\n").first.trim();
        sendToController.text = _address ?? "";

        _setValidAddressProviders(_address);
        setState(() {
          _addressToggleFlag = sendToController.text.isNotEmpty;
        });
      }
    } catch (e, s) {
      Logging.instance.e(
        "Error processing QR code data",
        error: e,
        stackTrace: s,
      );
    }
  }

  void _setValidAddressProviders(String? address) {
    final wallet = ref.read(pWallets).getWallet(walletId);
    ref.read(pValidSendToAddress.notifier).state =
        wallet.cryptoCurrency.validateAddress(address ?? "") ||
        pivxNameFor(coin, address) != null;
  }

  /// PIVX.name names always point to shield addresses.
  bool get _sendsToShield =>
      coin is Pivx &&
      ((coin as Pivx).isShieldAddress(_address ?? "") ||
          pivxNameFor(coin, _address) != null);

  void _applyUri(PaymentUriData paymentData) {
    try {
      // auto fill address
      _address = paymentData.address;
      sendToController.text = _address!;

      // shield memo
      memoController.text = truncateUtf8(
        paymentData.additionalParams['memo'] ?? "",
        kPivxMaxMemoBytes,
      );

      // autofill notes field.
      if (paymentData.message != null) {
        noteController.text = paymentData.message!;
      } else if (paymentData.label != null) {
        noteController.text = paymentData.label!;
      }

      // autofill amount field
      if (paymentData.amount != null) {
        final amount = Decimal.parse(paymentData.amount!)
            .toAmount(fractionDigits: coin.fractionDigits);
        cryptoAmountController.text = ref
            .read(pAmountFormatter(coin))
            .format(amount, withUnitName: false);
        ref.read(pSendAmount.notifier).state = amount;
      }

      // Trigger validation after pasting.
      _setValidAddressProviders(_address);
      setState(() {
        _addressToggleFlag = sendToController.text.isNotEmpty;
      });
    } catch (e, s) {
      Logging.instance.e("Error applying URI", error: e, stackTrace: s);
    }
  }

  void _setAddress(String content, {bool setController = true}) {
    if (setController) {
      sendToController.text = content;
    }
    _address = content;
  }

  Future<void> pasteAddress() async {
    final ClipboardData? data = await clipboard.getData(Clipboard.kTextPlain);
    if (data?.text != null && data!.text!.isNotEmpty) {
      String content = data.text!.trim();
      if (content.contains("\n")) {
        content = content.substring(0, content.indexOf("\n")).trim();
      }

      try {
        final paymentData = AddressUtils.parsePaymentUri(
          content,
          logging: Logging.instance,
        );
        if (paymentData != null &&
            paymentData.coin?.uriScheme == coin.uriScheme) {
          _applyUri(paymentData);
        } else {
          sendToController.text = content;
          _address = content;

          _setValidAddressProviders(_address);
          setState(() {
            _addressToggleFlag = sendToController.text.isNotEmpty;
          });
        }
      } catch (e) {
        // If parsing fails, treat it as a plain address.
        _setAddress(content);

        // Trigger validation after pasting.
        _setValidAddressProviders(_address);
        setState(() {
          _addressToggleFlag = sendToController.text.isNotEmpty;
        });
      }
    }
  }

  void fiatTextFieldOnChanged(String baseAmountString) {
    final baseAmount = Amount.tryParseFiatString(
      baseAmountString,
      locale: ref.read(localeServiceChangeNotifierProvider).locale,
    );
    final Amount? amount;
    if (baseAmount != null) {
      final _price = ref
          .read(priceAnd24hChangeNotifierProvider)
          .getPrice(coin)
          ?.value;

      if (_price == null || _price == Decimal.zero) {
        amount = Decimal.zero.toAmount(fractionDigits: coin.fractionDigits);
      } else {
        amount = baseAmount <= Amount.zero
            ? Decimal.zero.toAmount(fractionDigits: coin.fractionDigits)
            : (baseAmount.decimal / _price)
                  .toDecimal(scaleOnInfinitePrecision: coin.fractionDigits)
                  .toAmount(fractionDigits: coin.fractionDigits);
      }
      if (_cachedAmountToSend != null && _cachedAmountToSend == amount) {
        return;
      }
      _cachedAmountToSend = amount;

      final amountString = ref
          .read(pAmountFormatter(coin))
          .format(amount, withUnitName: false);

      _cryptoAmountChangeLock = true;
      cryptoAmountController.text = amountString;
      _cryptoAmountChangeLock = false;
    } else {
      amount = Decimal.zero.toAmount(fractionDigits: coin.fractionDigits);
      _cryptoAmountChangeLock = true;
      cryptoAmountController.text = "";
      _cryptoAmountChangeLock = false;
    }
    ref.read(pSendAmount.notifier).state = amount;
  }

  String _getSendAllTitle(bool showCoinControl, Set<UTXO> selectedUTXOs) {
    if (showCoinControl && selectedUTXOs.isNotEmpty) {
      return l10n.sendAllSelected;
    }

    return l10n.sendAllTicker(coin.ticker);
  }

  Amount _selectedUtxosAmount(Set<UTXO> utxos) => Amount(
    rawValue: utxos.map((e) => BigInt.from(e.value)).reduce((v, e) => v += e),
    fractionDigits: ref.read(pWalletCoin(walletId)).fractionDigits,
  );

  Future<void> _sendAllTapped(bool showCoinControl) async {
    // PIVX never takes the fee out of the amount silently: sending
    // everything ticks "Subtract fee from amount" where the user sees it.
    if (coin is Pivx && !_pivxSubtractFee) {
      setState(() => _pivxSubtractFee = true);
    }
    final Amount amount;

    if (showCoinControl && ref.read(desktopUseUTXOs).isNotEmpty) {
      amount = _selectedUtxosAmount(ref.read(desktopUseUTXOs));
    } else {
      amount = _spendable;
    }

    cryptoAmountController.text = ref
        .read(pAmountFormatter(coin))
        .format(amount, withUnitName: false);
  }

  void _showDesktopCoinControl() async {
    if (coin is Pivx) return _showPivxCoinControl();
    final amount = ref.read(pSendAmount);
    await showDialog<void>(
      context: context,
      builder: (context) => DesktopCoinControlUseDialog(
        walletId: widget.walletId,
        amountToSend: amount,
      ),
    );
  }

  /// PIVX coin control: transparent outputs or shield notes (whichever
  /// balance is spent), with the summary of what the send needs.
  Future<void> _showPivxCoinControl() async {
    final fromShield = _fromShield;
    final sendAmount = ref.read(pSendAmount);
    Amount? amount = sendAmount;
    if (amount != null && amount != _spendable && !_pivxSubtractFee) {
      final wallet = ref.read(pWallets).getWallet(walletId);
      if (wallet is PivxWallet) {
        amount += await wallet.estimateShieldFee(
          amount: amount,
          fromShield: fromShield,
          toShield: _sendsToShield,
        );
      }
    }
    if (!mounted) return;
    final result = await Navigator.of(context).pushNamed(
      CoinControlView.routeName,
      arguments: Tuple5(
        walletId,
        CoinControlViewType.use,
        amount,
        ref.read(desktopUseUTXOs),
        (
          shieldNotes: fromShield,
          sendAmount: sendAmount,
          toShield: _sendsToShield,
          subtractFee: _pivxSubtractFee,
        ),
      ),
    );
    if (result is Set<UTXO> && mounted) {
      ref.read(desktopUseUTXOs.notifier).state = result;
    }
  }

  Future<void> _pickPivxChangeAddress() async {
    final fromShield = _fromShield;
    final picked = await showDialog<String>(
      context: context,
      builder: (context) => DesktopDialog(
        maxWidth: 580,
        maxHeight: 640,
        child: PivxChangeAddressSheet(
          walletId: walletId,
          coin: coin as Pivx,
          current: _pivxChange,
          shield: fromShield,
        ),
      ),
    );
    if (picked != null && mounted) {
      final value = picked.isEmpty ? null : picked;
      setState(() {
        if (fromShield) {
          _pivxShieldChangeAddress = value;
        } else {
          _pivxChangeAddress = value;
        }
      });
    }
  }

  @override
  void initState() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      ref.refresh(feeSheetSessionCacheProvider);
      ref.read(pValidSendToAddress.notifier).state = false;
    });

    _data = widget.autoFillData;
    walletId = widget.walletId;
    coin = ref.read(pWalletInfo(walletId)).coin;
    clipboard = widget.clipboard;

    sendToController = TextEditingController();
    cryptoAmountController = TextEditingController();
    baseAmountController = TextEditingController();
    memoController = TextEditingController();
    nonceController = TextEditingController();
    noteController = TextEditingController();

    onCryptoAmountChanged = _cryptoAmountChanged;
    cryptoAmountController.addListener(onCryptoAmountChanged);

    // A pivx: payment link opened for this wallet.
    final link = ref.read(pDesktopPaymentLink);
    if (link != null && link.walletId == walletId) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        ref.read(pDesktopPaymentLink.notifier).state = null;
        if (mounted) _applyUri(link.data);
      });
    }

    if (_data != null) {
      final hasAmount = _data.amount != null;
      if (hasAmount) {
        _cryptoAmountChangeLock = true;
        cryptoAmountController.text = ref
            .read(pAmountFormatter(coin))
            .format(
              _data.amount!.toAmount(fractionDigits: coin.fractionDigits),
              withUnitName: false,
            );
        _cryptoAmountChangeLock = false;
      }
      sendToController.text = _data.contactLabel;
      _address = _data.address;
      _addressToggleFlag = true;

      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (hasAmount) {
          _cryptoAmountChanged();
        }
        _setValidAddressProviders(_address);
      });
    }

    _cryptoFocus.addListener(() {
      if (!_cryptoFocus.hasFocus && !_baseFocus.hasFocus) {
        if (ref.read(pSendAmount) == null) {
          if (ref.read(sendAmountProvider) != Amount.zero && mounted) {
            ref.read(sendAmountProvider.notifier).state = Amount.zero;
          }
        } else {
          ref.read(sendAmountProvider.notifier).state = ref.read(pSendAmount)!;
        }
      }
    });

    _baseFocus.addListener(() {
      if (!_cryptoFocus.hasFocus && !_baseFocus.hasFocus) {
        if (ref.read(pSendAmount) == null) {
          ref.refresh(sendAmountProvider);
        } else {
          ref.read(sendAmountProvider.notifier).state = ref.read(pSendAmount)!;
        }
      }
    });

    super.initState();
  }

  @override
  void dispose() {
    cryptoAmountController.removeListener(onCryptoAmountChanged);

    sendToController.dispose();
    cryptoAmountController.dispose();
    baseAmountController.dispose();
    memoController.dispose();
    nonceController.dispose();
    noteController.dispose();

    _addressFocusNode.dispose();
    _cryptoFocus.dispose();
    _baseFocus.dispose();
    _memoFocus.dispose();
    _nonceFocusNode.dispose();
    _noteFocus.dispose();
    super.dispose();
  }

  /// One of the PIVX balances to send from, with what it can spend.
  Widget _balanceChoice({
    required String title,
    required Balance balance,
    required bool selected,
    required VoidCallback onTap,
  }) {
    final colors = Theme.of(context).extension<StackColors>()!;
    return MouseRegion(
      cursor: SystemMouseCursors.click,
      child: GestureDetector(
        onTap: onTap,
        child: RoundedContainer(
          color: selected ? colors.textFieldDefaultBG : Colors.transparent,
          borderColor: selected
              ? colors.accentColorBlue
              : colors.textFieldDefaultBG,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                title,
                style: STextStyles.desktopTextExtraExtraSmall(context),
              ),
              const SizedBox(height: 4),
              Text(
                ref.watch(pAmountFormatter(coin)).format(balance.spendable),
                style: STextStyles.desktopTextExtraSmall(context)
                    .copyWith(color: colors.textDark),
              ),
            ],
          ),
        ),
      ),
    );
  }

